#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  int fill;  int count;  LPPOINT pt;  } Queue_Poly;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void ClearPoly(SQueue& q,void* s)  {  Queue_Poly* p = (Queue_Poly*)s;  delete [] p->pt;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintPoly(DefinePaint)  {  QueueP(Queue_Poly);  switch ( p->fill )    {    default:    case 0: ::Polyline    ( hDC, p->pt, p->count );break;    case 1: ::Polygon     ( hDC, p->pt, p->count );break;    case 2: ::PolyBezier  ( hDC, p->pt, p->count );break;    case 3: ::PolyBezierTo( hDC, p->pt, p->count );break;    case 4: ::PolylineTo  ( hDC, p->pt, p->count );break;    }  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~static void AddPoly( Queue_Poly* p, char* value )  {  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintPoly;  p->clear = &ClearPoly;  //  POINT pt = {0,0};  while ( ::ParserPoint(value,pt) )    {    if ( (p->count % 10) == 0 )      {      LPPOINT point = new POINT[p->count+10];      if ( p->pt )        {        memcpy( point, p->pt, p->count*sizeof(POINT) );        delete [] p->pt;        }      p->pt = point;      }    p->pt[p->count++] = pt;    }  //  if ( p->pt )  ::SetRect( &p->mRect, p->pt[0].x, p->pt[0].y, p->pt[0].x+10, p->pt[0].y+10 );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddPolyline(DefineTegs)  {  AddQueueEx(Queue_Poly);  p->fill = 0;  AddPoly( p, teg[0].value );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddPolygon(DefineTegs)  {  AddQueueEx(Queue_Poly);  p->fill = 1;  AddPoly( p, teg[0].value );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~